    used = set()
    for profile in UserProfile.objects.select_related('user').order_by('pk'):
        user = profile.user
        full_name = f'{user.first_name} {user.last_name}'.strip()
        base = (slugify(full_name) or slugify(user.username) or 'person')[:150]
        slug, n = base, 2
        while slug in used:
            slug, n = f'{base}-{n}', n + 1
        used.add(slug)
        profile.slug = slug
        profile.save(update_fields=['slug'])


